"""Upgrade the original standalone v0.1 dashboard to v0.2 with offline CSV import.
Run `python build.py` first only if regenerating the v0.1 HTML, then `python upgrade_v02.py`.
"""
from pathlib import Path
p=Path(__file__).resolve().parent/'index.html'
s=p.read_text()
if 'id="historical-module"' in s:
 print('Already upgraded');raise SystemExit(0)
style='''<style>
.import-row{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:10px 0}.import-row label{border:1px solid #cbd6e5;border-radius:9px;padding:9px 12px;background:white;cursor:pointer;font-size:13px}.import-row input[type=file]{max-width:240px}.chart-wrap{width:100%;height:280px;overflow:hidden}.chart-wrap svg{width:100%;height:100%;display:block}.chart-wrap text{fill:#63758c;font:11px system-ui,sans-serif}.chart-wrap .gridline{stroke:#e2e8f1;stroke-width:1}.chart-wrap .line{fill:none;stroke:#1768ad;stroke-width:2.7;stroke-linecap:round;stroke-linejoin:round}.chart-wrap .dot{fill:#1768ad}.pill{display:inline-block;background:#eaf1fa;border:1px solid #d5e4f5;border-radius:20px;padding:3px 9px;font-size:11px;color:#355e86}.alert{padding:11px;border-radius:8px;background:#fff4e6;color:#885313;font-size:12px}.good{color:#168061!important}.local-table{max-height:320px;overflow:auto}.three-cols{display:grid;grid-template-columns:1.2fr 1fr;gap:18px}@media(max-width:850px){.three-cols{grid-template-columns:1fr}}
</style>'''
s=s.replace('</head>',style+'</head>')
module='''<div class="section card" id="historical-module"><div class="hero" style="margin-bottom:8px"><div><h2>Historical industry time series</h2><p>Import a normalized export of official monthly NAICS receipts. Trends and YoY growth are calculated from actual rows only.</p></div><span class="pill" id="history-state">Snapshot only</span></div><div class="import-row"><label for="historical-file">Choose historical CSV</label><input id="historical-file" type="file" accept=".csv,text/csv" aria-label="Import monthly industry CSV"><select id="history-level" aria-label="Series type"><option value="industry">Industries</option><option value="retail">Retail subsectors</option></select><select id="history-sector" aria-label="Historical sector"><option value="__total__">Total reported in file</option></select><button id="reset-history">Reset</button></div><div id="history-msg" class="status">Expected columns: period, level, name, receipts. Optional: group. See <code>monthly_template.csv</code>. A single month does not constitute a historical series.</div><div class="three-cols"><div class="chart-wrap" id="history-chart"></div><div><div class="kpi-label">Latest selected observation</div><div class="kpi" id="history-latest">—</div><div class="sub" id="history-latest-date">Load monthly rows to begin</div><div style="margin-top:18px" class="kpi-label">True year-over-year growth</div><div class="kpi" id="history-yoy">—</div><div class="sub">Calculated from the same sector exactly 12 months earlier; not interpolated.</div><p class="status" id="history-count" style="margin-top:20px"></p></div></div><div class="note">Historical files are read locally by your browser; nothing is uploaded to a server. The historical mode does not substitute for Comptroller reporting and should preserve original file vintages.</div></div>
<div class="section card" id="local-module"><h2>City-level monthly allocations explorer</h2><p>Import the CSV generated by <code>fetch_local.py</code>. County selections aggregate cities assigned to that county; they do not represent the county government's revenue or total county taxable sales.</p><div class="import-row"><label for="local-file">Choose local allocations CSV</label><input id="local-file" type="file" accept=".csv,text/csv" aria-label="Import local allocations CSV"><select id="local-county" aria-label="County"><option>Upload a CSV first</option></select><select id="local-period" aria-label="Report month"><option>—</option></select></div><div id="local-msg" class="status">No city-level allocation file loaded. Fetch one using <code>python fetch_local.py --year 2026 --output local_2026.csv</code>.</div><div class="local-table"><table><thead><tr><th>City</th><th class="num">Allocation</th><th class="num">Prior year</th><th class="num">YoY</th></tr></thead><tbody id="local-rows"><tr><td colspan="4">No source data loaded.</td></tr></tbody></table></div></div>'''
s=s.replace('<div class="section cols"><section class="card"><h2>City & county explorer</h2>', module+'<div class="section cols"><section class="card"><h2>City & county explorer</h2>')
js=r'''<script>
/* v0.2 history and local CSV readers. RFC4180 escaped quotes, commas and multiline fields. */
(function(){
function parseCSV(raw){raw=raw.replace(/^\uFEFF/,'');const out=[],row=[];let word='',quoted=false;for(let i=0;i<raw.length;i++){const c=raw[i];if(c==='"'){if(quoted&&raw[i+1]==='"'){word+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(word);word=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&raw[i+1]==='\n')i++;row.push(word);if(row.some(x=>x.trim()))out.push(row.slice());row.length=0;word=''}else word+=c;}if(quoted)throw Error('Unclosed quote in CSV');if(word.length||row.length){row.push(word);out.push(row)}if(!out.length)throw Error('CSV is empty');const keys=out.shift().map(x=>x.trim().toLowerCase());return out.map((r,i)=>Object.fromEntries(keys.map((k,j)=>[k,(r[j]||'').trim()])))}
const toNumber=v=>Number(String(v||'').replace(/[$,%\s]/g,'').replace(/,/g,''));
const fmoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const fmtShort=n=>Math.abs(n)>=1e9?'$'+(n/1e9).toFixed(2)+'B':Math.abs(n)>=1e6?'$'+(n/1e6).toFixed(1)+'M':fmoney(n);
const el=id=>document.getElementById(id);let history=[],locals=[];
function selectedHistory(){return history.filter(r=>r.level===el('history-level').value&&(el('history-sector').value==='__total__'||r.name===el('history-sector').value));}
function renderHistory(){const lev=el('history-level').value,opts=[...new Set(history.filter(r=>r.level===lev).map(r=>r.name))].sort();const old=el('history-sector').value;el('history-sector').innerHTML='<option value="__total__">Sum of included sectors</option>'+opts.map(n=>'<option value="'+escapeText(n)+'">'+escapeText(n)+'</option>').join('');el('history-sector').value=opts.includes(old)?old:'__total__';renderTrend()}
function escapeText(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function renderTrend(){let rows=selectedHistory(),map=new Map();for(const r of rows)map.set(r.period,(map.get(r.period)||0)+r.receipts);let data=[...map].sort((a,b)=>a[0].localeCompare(b[0]));el('history-count').textContent=data.length+' observed month(s), '+rows.length+' source rows.';let latest=data.at(-1);el('history-latest').textContent=latest?fmtShort(latest[1]):'—';el('history-latest-date').textContent=latest?latest[0]:'No selected observations';let back=latest&&(Number(latest[0].slice(0,4))-1)+latest[0].slice(4);let earlier=data.find(d=>d[0]===back);el('history-yoy').textContent=latest&&earlier&&earlier[1]!==0?((latest[1]/earlier[1]-1)*100).toFixed(2)+'%':'Not available';const chart=el('history-chart');if(!data.length){chart.innerHTML='<p class="status">Load a historical CSV to display a time series.</p>';return;}let min=Math.min(...data.map(d=>d[1])),max=Math.max(...data.map(d=>d[1]));if(min===max){min=Math.max(0,min*.85);max=max*1.15||1;}const W=720,H=270,L=82,R=20,T=15,B=40,p= (x,i)=>L+i*(W-L-R)/Math.max(1,data.length-1),q=v=>T+(max-v)*(H-T-B)/(max-min);let path=data.map((d,i)=>(i?'L':'M')+p(d,i).toFixed(1)+','+q(d[1]).toFixed(1)).join(' ');let grids=Array.from({length:5},(_,i)=>{let v=min+(max-min)*(4-i)/4,y=q(v);return `<line class="gridline" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text x="${L-8}" y="${y+4}" text-anchor="end">${escapeText(fmtShort(v))}</text>`}).join('');let ticks=data.filter((_,i)=>i===0||i===data.length-1||i%Math.max(1,Math.ceil(data.length/7))===0).map((d)=>{let i=data.indexOf(d);return `<text x="${p(d,i)}" y="${H-12}" text-anchor="middle">${escapeText(d[0].slice(2))}</text>`}).join('');chart.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Observed monthly receipts trend for selected series">${grids}<path class="line" d="${path}"/>${data.length<30?data.map((d,i)=>`<circle class="dot" cx="${p(d,i)}" cy="${q(d[1])}" r="3.5"><title>${escapeText(d[0])}: ${escapeText(fmoney(d[1]))}</title></circle>`).join(''):''}${ticks}</svg>`;}
async function readFile(id){const f=el(id).files[0];if(!f)return null;if(f.size>40*1024*1024)throw Error('CSV too large (>40 MB). Use smaller year ranges.');return parseCSV(await f.text())}
el('historical-file').onchange=async()=>{try{const rows=await readFile('historical-file');if(!rows)return;const required=['period','level','name','receipts'];if(!rows.length||required.some(k=>!(k in rows[0])))throw Error('Missing columns. Required: '+required.join(', '));let seen=new Set();const parsed=rows.map((r,i)=>{let period=r.period,level=r.level.toLowerCase(),n=toNumber(r.receipts),name=r.name;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(period))throw Error('Invalid period on row '+(i+2));if(!['industry','retail'].includes(level))throw Error('Invalid level on row '+(i+2));if(!Number.isFinite(n)||n<0||!name)throw Error('Invalid receipts or missing name on row '+(i+2));let key=[period,level,name].join('|');if(seen.has(key))throw Error('Duplicate period/level/name: '+key);seen.add(key);return{period,level,name,receipts:n,group:r.group||''}});history=parsed;el('history-state').textContent='Imported • '+history.length+' observations';el('history-msg').textContent='Loaded '+history.length+' independently supplied observations. No data were imputed.';renderHistory()}catch(e){el('history-msg').textContent='Import failed: '+e.message;el('history-state').textContent='Snapshot only'}};
el('history-level').onchange=renderHistory;el('history-sector').onchange=renderTrend;el('reset-history').onclick=()=>{history=[];el('historical-file').value='';el('history-state').textContent='Snapshot only';el('history-msg').textContent='Historical data cleared.';renderHistory()};
function renderLocal(){const county=el('local-county').value,period=el('local-period').value;let a=locals.filter(x=>x.county===county&&x.period===period).sort((x,y)=>y.payment-x.payment);el('local-rows').innerHTML=a.map(x=>`<tr><td>${escapeText(x.city)}</td><td class="num">${fmoney(x.payment)}</td><td class="num">${fmoney(x.prior)}</td><td class="num">${x.prior>0?((x.payment/x.prior-1)*100).toFixed(1)+'%':'—'}</td></tr>`).join('')||'<tr><td colspan="4">No records for this selection.</td></tr>';let s=a.reduce((v,x)=>v+x.payment,0);el('local-msg').textContent=a.length+' cities in '+county+' for '+period+'. Sum of city allocations: '+fmoney(s)+'. Not countywide taxable sales.';}
el('local-file').onchange=async()=>{try{let rows=await readFile('local-file');if(!rows)return;let req=['county','city','net_payment_this_period','comparable_payment_prior_year','report_month','report_year'];if(!rows.length||req.some(k=>!(k in rows[0])))throw Error('Expected fetch_local.py CSV with columns: '+req.join(', '));let out=rows.map((r,i)=>{let m=Number(r.report_month),y=Number(r.report_year),payment=toNumber(r.net_payment_this_period),prior=toNumber(r.comparable_payment_prior_year);if(!Number.isInteger(m)||m<1||m>12||!Number.isInteger(y)||y<2000||y>2100||!Number.isFinite(payment)||!Number.isFinite(prior))throw Error('Invalid month/year/payment on row '+(i+2));return{county:r.county,city:r.city,payment,prior,period:y+'-'+String(m).padStart(2,'0')}});locals=out;const counties=[...new Set(out.map(x=>x.county))].sort(),months=[...new Set(out.map(x=>x.period))].sort();el('local-county').innerHTML=counties.map(c=>`<option value="${escapeText(c)}">${escapeText(c)}</option>`).join('');el('local-period').innerHTML=months.map(c=>`<option value="${c}">${c}</option>`).join('');if(counties.includes('Harris'))el('local-county').value='Harris';el('local-period').value=months.at(-1);renderLocal()}catch(e){el('local-msg').textContent='Import failed: '+e.message}};el('local-county').onchange=renderLocal;el('local-period').onchange=renderLocal;renderHistory();
})();
</script>'''
s=s.replace('</body>',js+'</body>')
s=s.replace('Prototype v0.1','Prototype v0.2').replace('PROTOTYPE · SEP 2026','PROTOTYPE · SEP 2026')
p.write_text(s)
print('Upgraded to v0.2:',p)
